import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;

import net.sf.cglib.proxy.Enhancer;
import net.sf.cglib.proxy.MethodInterceptor;
import net.sf.cglib.proxy.MethodProxy;

// ========== 接口与实现 ==========
interface UserService {
    void save(String name);
    String find(Long id);
}

class UserServiceImpl implements UserService {
    @Override
    public void save(String name) {
        System.out.println("  [真实] 保存用户: " + name);
    }
    @Override
    public String find(Long id) {
        return "user-" + id;
    }
}

// ========== 1. 静态代理 ==========
class UserServiceStaticProxy implements UserService {
    private final UserService target;
    UserServiceStaticProxy(UserService target) { this.target = target; }

    @Override
    public void save(String name) {
        System.out.println("[静态代理] 前置: 开启事务");
        target.save(name);
        System.out.println("[静态代理] 后置: 提交事务");
    }
    @Override
    public String find(Long id) {
        System.out.println("[静态代理] 前置: 权限校验");
        String result = target.find(id);
        System.out.println("[静态代理] 后置: 记录日志");
        return result;
    }
}

// ========== 2. JDK 动态代理 ==========
class JdkInvocationHandler implements InvocationHandler {
    private final Object target;
    JdkInvocationHandler(Object target) { this.target = target; }

    @Override
    public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
        System.out.println("[JDK代理] 前置: " + method.getName());
        Object result = method.invoke(target, args);
        System.out.println("[JDK代理] 后置: " + method.getName());
        return result;
    }
}

// ========== 3. CGLIB 代理 ==========
class CglibMethodInterceptor implements MethodInterceptor {
    @Override
    public Object intercept(Object obj, Method method, Object[] args,
                            MethodProxy methodProxy) throws Throwable {
        System.out.println("[CGLIB] 前置: " + method.getName());
        Object result = methodProxy.invokeSuper(obj, args);
        System.out.println("[CGLIB] 后置: " + method.getName());
        return result;
    }
}

public class ProxyPatternDemo {
    public static void main(String[] args) {
        UserService real = new UserServiceImpl();

        // 静态代理
        System.out.println("=== 静态代理 ===");
        UserService staticProxy = new UserServiceStaticProxy(real);
        staticProxy.save("Alice");
        System.out.println(staticProxy.find(1L));

        // JDK 动态代理
        System.out.println("\n=== JDK 动态代理 ===");
        UserService jdkProxy = (UserService) Proxy.newProxyInstance(
                real.getClass().getClassLoader(),
                real.getClass().getInterfaces(),
                new JdkInvocationHandler(real));
        jdkProxy.save("Bob");
        System.out.println(jdkProxy.find(2L));

        // CGLIB（无需接口，直接代理类）
        System.out.println("\n=== CGLIB 代理 ===");
        Enhancer enhancer = new Enhancer();
        enhancer.setSuperclass(UserServiceImpl.class);
        enhancer.setCallback(new CglibMethodInterceptor());
        UserServiceImpl cglibProxy = (UserServiceImpl) enhancer.create();
        cglibProxy.save("Charlie");
        System.out.println(cglibProxy.find(3L));
    }
}

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

// ========== 复现：自调用导致 @Transactional 失效 ==========
@Service
public class OrderService {

    // createOrder 和 sendNotification 在同一个 Bean
    // createOrder 内部 this.sendNotification() 绕过代理
    // sendNotification 上的 @Transactional 不生效
    @Transactional
    public void createOrder(String orderId) {
        System.out.println("[createOrder] 保存订单: " + orderId);
        // 这里是 this.sendNotification()，走真实对象，不经过代理
        this.sendNotification(orderId);
    }

    @Transactional
    public void sendNotification(String orderId) {
        // 如果调用经过代理，这里会有一个独立事务
        // 但自调用时这个注解不生效，和 createOrder 共用同一个事务
        System.out.println("[sendNotification] 发送通知: " + orderId);
    }
}

// ========== 修复方式一：拆 Bean ==========
@Service
public class OrderServiceFixed {
    @Autowired
    private NotificationService notificationService; // 注入另一个 Bean

    @Transactional
    public void createOrder(String orderId) {
        System.out.println("[createOrder] 保存订单: " + orderId);
        notificationService.send(orderId); // 经过代理，独立事务生效
    }
}

@Service
public class NotificationService {
    @Transactional
    public void send(String orderId) {
        System.out.println("[send] 发送通知: " + orderId);
    }
}

// ========== 修复方式二：自注入 ==========
@Service
public class OrderServiceSelfInject {
    @Autowired
    private OrderServiceSelfInject self; // Spring 提前暴露的代理对象

    @Transactional
    public void createOrder(String orderId) {
        System.out.println("[createOrder] 保存订单: " + orderId);
        self.sendNotification(orderId); // 通过 self（代理）调用
    }

    @Transactional
    public void sendNotification(String orderId) {
        System.out.println("[sendNotification] 发送通知: " + orderId);
    }
}
